from pathlib import Path

# 1) Give SetupController a supported way to rebuild the selected device backend
# after button capture temporarily relinquishes hardware/discovery ownership.
controller_path = Path('src/mouse_control/setup_tui.py')
text = controller_path.read_text()
needle = '''    def restore_temporary_state(self) -> None:\n        try:\n            restore_dpi(self.backend, self.selected, self.choices.original_dpi)\n        except Exception:\n            pass\n\n'''
replacement = needle + '''    def refresh_discovery_backend(self, *, status: str | None = None) -> None:\n        \"\"\"Rebuild the selected device backend after temporary input ownership.\"\"\"\n        try:\n            if self.backend is not None:\n                self.backend.close()\n        except Exception:\n            pass\n        self.backend = self._backend_factory(self.selected)\n        self._discover_into_choices()\n        if status is not None:\n            self.status = status\n\n'''
if needle not in text:
    raise SystemExit('controller insertion point not found')
text = text.replace(needle, replacement, 1)
controller_path.write_text(text)

# 2) Restore the proven ownership rule in the current discovery-first curses TUI.
curses_path = Path('src/mouse_control/setup_tui_curses.py')
text = curses_path.read_text()
text = text.replace('import curses\n', 'import curses\nimport errno\n', 1)
old = '''    def _button_editor(self) -> None:\n        assert self.stdscr is not None\n        device = None\n        try:\n            device = InputDevice(self.controller.selected.path)\n            device.grab()\n        except OSError as exc:\n            if device is not None:\n                device.close()\n            raise ButtonCaptureError(f\"Could not reserve the mouse for button capture: {exc}\") from exc\n\n        nodelay_enabled = False\n        try:\n            self.stdscr.nodelay(True)\n            nodelay_enabled = True\n            while True:\n                self._modal(\n                    \"Button mapping\",\n                    [\n                        \"Press a mouse button to configure it.\",\n                        \"Existing mappings stay unchanged until you select a new action.\",\n                    ],\n                    prompt=\"Enter Finish   Esc Finish\",\n                )\n                key = self.stdscr.getch()\n                if key == curses.KEY_RESIZE:\n                    continue\n                if key in (10, 13, curses.KEY_ENTER, 27):\n                    break\n                try:\n                    events = device.read()\n                except BlockingIOError:\n                    events = ()\n                except OSError as exc:\n                    raise ButtonCaptureError(f\"Mouse disconnected during button capture: {exc}\") from exc\n                for event in events:\n                    if event.type != ecodes.EV_KEY or event.value != 1:\n                        continue\n                    button = get_button_name(event.code)\n                    self.stdscr.nodelay(False)\n                    action = self._choose_button_action(button)\n                    self.stdscr.nodelay(True)\n                    if action is not None:\n                        self.controller.apply_button_mapping(button, action)\n                    break\n                curses.napms(20)\n        finally:\n            if nodelay_enabled:\n                self.stdscr.nodelay(False)\n            try:\n                device.ungrab()\n            except OSError:\n                pass\n            device.close()\n'''
new = '''    @staticmethod\n    def _input_error_message(exc: OSError, *, phase: str) -> str:\n        if exc.errno in {errno.EAGAIN, errno.EWOULDBLOCK, errno.EBUSY}:\n            return (\n                f\"Input device busy during {phase}. Mouse Control kept the current \"\n                \"mappings unchanged.\"\n            )\n        return f\"Input capture failed during {phase}: {exc}\"\n\n    def _button_editor(self) -> None:\n        \"\"\"Give button capture sole Mouse Control ownership of the evdev node.\"\"\"\n        assert self.stdscr is not None\n        device = None\n        nodelay_enabled = False\n\n        # Discovery/HID backends can retain readers while setup is open. Button\n        # remapping is a core invariant and requires an exclusive EVIOCGRAB, so\n        # release those resources before opening the selected event node.\n        try:\n            self.controller.backend.close()\n        except Exception:\n            pass\n\n        try:\n            try:\n                device = InputDevice(self.controller.selected.path)\n            except OSError as exc:\n                raise ButtonCaptureError(\n                    self._input_error_message(exc, phase=\"opening selected mouse\")\n                ) from exc\n\n            try:\n                device.grab()\n            except OSError as exc:\n                raise ButtonCaptureError(\n                    self._input_error_message(exc, phase=\"exclusive mouse grab\")\n                ) from exc\n\n            self.stdscr.nodelay(True)\n            nodelay_enabled = True\n            while True:\n                self._modal(\n                    \"Button mapping\",\n                    [\n                        \"Press a mouse button to configure it.\",\n                        \"Existing mappings stay unchanged until you select a new action.\",\n                    ],\n                    prompt=\"Enter Finish   Esc Finish\",\n                )\n                key = self.stdscr.getch()\n                if key == curses.KEY_RESIZE:\n                    continue\n                if key in (10, 13, curses.KEY_ENTER, 27):\n                    break\n                try:\n                    events = device.read()\n                except BlockingIOError:\n                    events = ()\n                except OSError as exc:\n                    raise ButtonCaptureError(\n                        self._input_error_message(exc, phase=\"reading mouse events\")\n                    ) from exc\n                for event in events:\n                    if event.type != ecodes.EV_KEY or event.value != 1:\n                        continue\n                    button = get_button_name(event.code)\n                    self.stdscr.nodelay(False)\n                    action = self._choose_button_action(button)\n                    self.stdscr.nodelay(True)\n                    if action is not None:\n                        self.controller.apply_button_mapping(button, action)\n                    break\n                curses.napms(20)\n        finally:\n            if nodelay_enabled:\n                self.stdscr.nodelay(False)\n            if device is not None:\n                try:\n                    device.ungrab()\n                except OSError:\n                    pass\n                try:\n                    device.close()\n                except OSError:\n                    pass\n            try:\n                self.controller.refresh_discovery_backend(\n                    status=\"Button capture finished; hardware capabilities refreshed.\"\n                )\n            except Exception as exc:\n                self.controller.status = (\n                    f\"Button capture ended; capability refresh failed: {exc}\"\n                )\n'''
if old not in text:
    raise SystemExit('button editor block not found')
text = text.replace(old, new, 1)
curses_path.write_text(text)

# 3) Dedicated core-remapping regression coverage.
test_path = Path('tests/test_button_capture_ownership.py')
test_path.write_text('''import errno\nfrom types import SimpleNamespace\n\nfrom mouse_control.setup_tui_curses import CursesSetupApp\n\n\nclass Backend:\n    def __init__(self):\n        self.closed = False\n\n    def close(self):\n        self.closed = True\n\n\nclass StdScr:\n    def nodelay(self, _value):\n        pass\n\n    def getch(self):\n        return 10\n\n\ndef test_button_capture_releases_backend_before_exclusive_grab(monkeypatch):\n    backend = Backend()\n    refreshed = []\n\n    class Device:\n        def __init__(self, path):\n            assert path == \"/dev/input/titan\"\n\n        def grab(self):\n            assert backend.closed is True\n\n        def ungrab(self):\n            pass\n\n        def close(self):\n            pass\n\n    controller = SimpleNamespace(\n        backend=backend,\n        selected=SimpleNamespace(path=\"/dev/input/titan\"),\n        status=\"\",\n        refresh_discovery_backend=lambda **kwargs: refreshed.append(kwargs),\n    )\n    app = CursesSetupApp(controller)\n    app.stdscr = StdScr()\n    app._modal = lambda *args, **kwargs: None\n    monkeypatch.setattr(\"mouse_control.setup_tui_curses.InputDevice\", Device)\n\n    app._button_editor()\n\n    assert refreshed == [{\"status\": \"Button capture finished; hardware capabilities refreshed.\"}]\n\n\ndef test_errno11_is_recoverable_and_preserves_mappings_message():\n    exc = BlockingIOError(errno.EAGAIN, \"Resource temporarily unavailable\")\n    message = CursesSetupApp._input_error_message(exc, phase=\"exclusive mouse grab\")\n    assert \"busy during exclusive mouse grab\" in message\n    assert \"mappings unchanged\" in message\n''')
print('restored button-capture ownership handoff and regression coverage')
